head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > M > enableAllDate]<br/>컴포넌트에서 setDisableAfterDate(), setDisableBeforeDate() 메소드로 설정된 값을 제거합니다.",
    "validation" : [
        "setDisabledDate() 메소드로 설정된 값은 제거 되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // comp 생성 함수 호출
    $c.gcm.createBasicInputCalendar();

    scwin.btn_setDisabledDate_onclick();
}



scwin.btn_getSelectedDate_onclick = function (e) {
    const element = document.querySelector('div[id*="calendar_currentDate"]');
    let disabledDates = [];

    if (element) {    
        wf_body_bottom.getObj("scwin").setReturnValue("선택일 : " + element.textContent);           

        // 모든 td 태그를 가져온 후, 필터링하여 원하는 클래스를 가진 태그를 선택합니다.
        const disabledTds = Array.from(document.querySelectorAll('td')).filter(td => 
            td.classList.contains('w2calendar_date_disable')
        );       

        // 각 td 요소의 textContent를 배열에 넣습니다.
        disabledTds.forEach(td => {
            disabledDates.push(td.textContent);
        });   

        wf_body_bottom.getObj("scwin").setReturnValue("취소선 적용일 : " + disabledDates);        
    }	
    else {
        wf_body_bottom.getObj("scwin").setReturnValue('팝업 달력을 한번 오픈해야 정보 가져올 수 있음');        
    }
};



scwin.btn_setDisabledDate_onclick = function (e) {    
	target1.setDisabledDate("20251101");
};



scwin.btn_enableAllDate_onclick = function (e) {
    target1.enableAllDate();
};
